/**
 * Errors raised by the store. Every variant carries a details that is safe to log: none
 * contains key material or document text.
 */
public 
enum WarmError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * An argument failed validation (identifier, JSON, option range, embedding length).
     */
    case InvalidInput(details: String
    )
    /**
     * Another engine, in this process or another, holds the store directory.
     */
    case StoreLocked(details: String
    )
    /**
     * The encryption key is missing, wrong, or does not match the store.
     */
    case Encryption(details: String
    )
    /**
     * The store was created with different dimensions, embedding space or encryption setting.
     */
    case IncompatibleStore(details: String
    )
    /**
     * A path that must exist does not.
     */
    case NotFound(details: String
    )
    /**
     * A path that must be absent or empty is not.
     */
    case AlreadyExists(details: String
    )
    /**
     * A snapshot failed verification, or the store's files are damaged.
     */
    case Corrupt(details: String
    )
    /**
     * The operating system refused a file operation.
     */
    case Io(details: String
    )
    /**
     * The store handle was closed.
     */
    case Closed
    /**
     * A bug or panic inside the engine.
     */
    case Internal(details: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension WarmError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeWarmError: FfiConverterRustBuffer {
    typealias SwiftType = WarmError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WarmError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            details: try FfiConverterString.read(from: &buf)
            )
        case 2: return .StoreLocked(
            details: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Encryption(
            details: try FfiConverterString.read(from: &buf)
            )
        case 4: return .IncompatibleStore(
            details: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotFound(
            details: try FfiConverterString.read(from: &buf)
            )
        case 6: return .AlreadyExists(
            details: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Corrupt(
            details: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Io(
            details: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Closed
        case 10: return .Internal(
            details: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WarmError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(details):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .StoreLocked(details):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .Encryption(details):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .IncompatibleStore(details):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .NotFound(details):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .AlreadyExists(details):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .Corrupt(details):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(details, into: &buf)
            
        
        case let .Io(details):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(details, into: &buf)
            
        
        case .Closed:
            writeInt(&buf, Int32(9))
        
        
        case let .Internal(details):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(details, into: &buf)
            
        }
    }
}


